widget.solution:
class Trie:
    def __init__(self):
        self.root = {'#n': 0}            # '#n': words through here

    def insert(self, word):
        node = self.root
        for ch in word:
            node = node.setdefault(ch, {'#n': 0})
        if not node.get('#end'):         # a new word
            node['#end'] = True
            node = self.root
            node['#n'] += 1
            for ch in word:
                node = node[ch]
                node['#n'] += 1

    def _walk(self, s):
        node = self.root
        for ch in s:
            if ch not in node:
                return None
            node = node[ch]
        return node

    def search(self, word):
        node = self._walk(word)
        return bool(node and node.get('#end'))

    def starts_with(self, prefix):
        return self._walk(prefix) is not None

    def count_prefix(self, prefix):
        node = self._walk(prefix)
        return node['#n'] if node else 0

widget.postlude:
def run_trie(ops):
    t = Trie()
    out = []
    for op, arg in ops:
        if op == 'insert': t.insert(arg)
        elif op == 'search': out.append(t.search(arg))
        elif op == 'starts_with': out.append(t.starts_with(arg))
        else: out.append(t.count_prefix(arg))
    return out

