def top_completions(words, prefix, k):
    root = {}
    for w in set(words):                 # build the trie
        node = root
        for ch in w:
            node = node.setdefault(ch, {})
        node['$'] = True
    node = root
    for ch in prefix:                    # walk to the prefix
        if ch not in node:
            return []
        node = node[ch]
    out = []
    def dfs(node, path):
        if len(out) >= k:
            return
        if '$' in node:
            out.append(prefix + path)
        for ch in sorted(c for c in node if c != '$'):
            dfs(node[ch], path + ch)
    dfs(node, '')
    return out[:k]
